insert into dnew values
(1, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'After a chest injury, ABGs show pH 7.26, PaCO2 52 mmHg, HCO3 25 mmol/L. This is:', '["Metabolic alkalosis", "Respiratory alkalosis", "Metabolic acidosis", "Respiratory acidosis"]'::jsonb, 3, 'Low pH (acidosis), high PaCO2 (respiratory cause) and normal HCO3 (not yet compensated): acute respiratory acidosis.', 'ABG & Electrolytes'),
(2, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Chvostek''s and Trousseau''s signs are clinical indicators of:', '["Hypomagnesaemia exclusively", "Hyperkalaemia", "Hypocalcaemia", "Hypernatraemia"]'::jsonb, 2, 'Chvostek''s sign (facial twitching on tapping the facial nerve) and Trousseau''s sign (carpal spasm with blood pressure cuff inflation) are classic bedside indicators of neuromuscular irritability from hypocalcaemia.', 'ABG & Electrolytes'),
(3, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Clotting factors are primarily synthesised by the:', '["Liver", "Spleen", "Kidneys", "Pancreas"]'::jsonb, 0, 'Most clotting factors are synthesised in the liver, which is why liver disease can impair coagulation.', 'ABG & Electrolytes'),
(4, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Accidental removal of the parathyroid glands during thyroidectomy results in:', '["Hyperthyroidism", "Hyperkalaemia", "Hypocalcaemia", "Hypoglycaemia"]'::jsonb, 2, 'Without the parathyroids, blood calcium drops, causing Trousseau''s and Chvostek''s signs.', 'ABG & Electrolytes'),
(5, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A postoperative patient with hypocalcemia (ionized Ca²⁺ 0.8 mmol/L) exhibits carpopedal spasm and laryngeal stridor. Which action takes priority?', '["Apply a nasal cannula at 2 L/min", "Give vitamin D supplements", "Infuse 10% calcium gluconate IV", "Administer oral calcium carbonate"]'::jsonb, 2, 'IV calcium gluconate is critical for acute, symptomatic hypocalcemia to reverse neuromuscular irritability and prevent respiratory arrest.', 'ABG & Electrolytes'),
(6, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'In a patient with hyperkalemia, which ECG change warrants IMMEDIATE intervention?', '["Peaked T waves", "ST-segment depression", "Sinus tachycardia", "First-degree AV block"]'::jsonb, 0, 'Peaked T waves are an early sign of hyperkalemia and may progress to life-threatening arrhythmias.', 'ABG & Electrolytes'),
(7, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient with hypermagnesemia (Mg²⁺ 4.5 mg/dL) has hypotension and absent deep tendon reflexes. Which intervention is MOST appropriate?', '["Give calcium chloride 10% IV", "Administer magnesium sulfate IV", "Infuse 0.9% normal saline bolus", "Start furosemide 40 mg IV"]'::jsonb, 0, 'Calcium antagonizes magnesium’s effects on neuromuscular and cardiovascular systems. Saline boluses and diuretics support excretion but do not directly counteract toxicity.', 'ABG & Electrolytes'),
(8, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'The kidney has more of which structure than any of the others listed?', '["Afferent arterioles", "Arcuate arteries", "Medullary pyramids", "Minor calyces"]'::jsonb, 0, 'Each kidney has about a million nephrons, each with its own afferent arteriole, far more than its calyces, pyramids or arcuate arteries.', 'ABG & Electrolytes'),
(9, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Positive Chvostek''s sign indicates:', '["Hypernatremia", "Hypercalcaemia", "Hypokalemia", "Hypocalcaemia"]'::jsonb, 3, 'A positive Chvostek''s sign (facial twitching on tapping) indicates hypocalcaemia.', 'ABG & Electrolytes'),
(10, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient with heart failure and severe hyponatremia (Na⁺ 115 mEq/L) develops seizures. Which intervention should the nurse initiate FIRST?', '["Start oral sodium chloride tablets", "Administer 3% hypertonic saline IV", "Give furosemide 40 mg IV", "Restrict oral fluid intake to 500 mL/day"]'::jsonb, 1, 'Severe symptomatic hyponatremia (e.g., seizures) requires rapid correction with 3% hypertonic saline to prevent cerebral edema and herniation. Fluid restriction and diuretics are adjunctive but not immediate for life-threatening symptoms.', 'ABG & Electrolytes'),
(11, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A completely normal pH on an ABG:', '["Only occurs in healthy people", "Always rules out any acid-base disorder", "Does NOT rule out a mixed disorder", "Means PaCO2 and HCO3 must also be normal"]'::jsonb, 2, 'Two opposing disorders (e.g. respiratory acidosis plus metabolic alkalosis) can cancel each other out, producing a falsely reassuring normal pH — always check all three values.', 'ABG & Electrolytes'),
(12, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'The process by which water and diffusible substances move together across a membrane in response to fluid pressure is:', '["Diffusion", "Active transport", "Filtration", "Osmosis"]'::jsonb, 2, 'Filtration moves water and small solutes together across a membrane under hydrostatic (fluid) pressure, as at the glomerulus.', 'ABG & Electrolytes'),
(13, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Characteristic ECG changes of hypokalaemia include:', '["Shortened QT interval", "Flattened T waves and prominent U waves", "Peaked T waves and widened QRS", "Complete absence of P waves in all cases"]'::jsonb, 1, 'Hypokalaemia classically produces flattened or inverted T waves and prominent U waves on ECG, along with potential ST depression.', 'ABG & Electrolytes'),
(14, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient with hypercalcemia is prescribed calcitonin. The nurse should monitor for:', '["Hyperphosphatemia", "Hypoglycemia", "Tachyphylaxis", "Hypocalcemia"]'::jsonb, 2, 'Calcitonin loses efficacy after 48 hours (tachyphylaxis). Hypocalcemia is rare; it primarily lowers calcium.', 'ABG & Electrolytes'),
(15, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A potassium chloride infusion of 40 mEq is ordered in 500 mL of NS to run over 4 hours via a peripheral line. What is the resulting rate of potassium delivery in mEq/hr, and is this within the generally accepted peripheral IV limit of 10 mEq/hr?', '["20 mEq/hr; exceeds the peripheral limit", "5 mEq/hr; well within the peripheral limit", "40 mEq/hr; grossly exceeds the peripheral limit", "10 mEq/hr; at the upper safe peripheral limit"]'::jsonb, 3, '40 mEq over 4 hours = 10 mEq/hr, which is at the commonly accepted maximum peripheral infusion limit and should be given on a monitored line with cardiac monitoring.', 'ABG & Electrolytes'),
(16, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Renal autoregulation maintains a relatively constant glomerular filtration rate across which approximate range of mean arterial pressure?', '["60-80 mmHg", "80-180 mmHg", "40-60 mmHg", "180-220 mmHg"]'::jsonb, 1, 'Through myogenic and tubuloglomerular feedback mechanisms, renal blood flow and GFR remain relatively stable across a MAP range of roughly 80-180 mmHg; below this, renal perfusion falls sharply.', 'ABG & Electrolytes'),
(17, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'On room air at sea level a patient has PaO₂ 60 mmHg and PaCO₂ 40 mmHg. The A–a gradient is about:', '["40 mmHg, raised, suggesting V/Q mismatch or shunt", "10 mmHg, normal for a young adult", "0 mmHg, normal, showing pure hypoventilation", "150 mmHg, equal to the inspired oxygen pressure"]'::jsonb, 0, 'PAO₂ = 0.21 × (760 − 47) − 40/0.8 ≈ 100 mmHg; 100 − 60 = 40. Normal is about 5–15 mmHg.', 'ABG & Electrolytes'),
(18, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Hypokalaemia that does not correct despite potassium replacement should prompt the nurse to check:', '["Serum urea, as it pushes K⁺ into cells", "Serum magnesium, as low Mg²⁺ causes renal K⁺ loss", "Serum sodium, as high Na⁺ blocks K⁺ uptake", "Serum albumin, as it binds most of the K⁺"]'::jsonb, 1, 'Correct magnesium first; potassium will then be retained.', 'ABG & Electrolytes'),
(19, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient with persistent vomiting has metabolic alkalosis and urine chloride below 20 mmol/L. This alkalosis is:', '["Saline-responsive; treat with 0.9% saline and potassium", "Saline-resistant; treat with spironolactone only", "Respiratory in origin; treat with rebreathing", "Due to mineralocorticoid excess; treat with surgery"]'::jsonb, 0, 'Low urine chloride shows chloride/volume depletion. Saline-resistant alkalosis has urine Cl⁻ above 20 (e.g. Conn''s).', 'ABG & Electrolytes'),
(20, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'The Haldane effect describes:', '["CO₂ diffusing 20 times faster than oxygen", "Hypoxic vasoconstriction in poorly ventilated lung", "Deoxygenated haemoglobin carrying more CO₂ than oxygenated Hb", "Oxygen release from Hb increasing as pH falls"]'::jsonb, 2, 'When high oxygen is given, Hb releases CO₂, which partly explains CO₂ rise in some COPD patients. The Bohr effect is the pH effect on O₂ release.', 'ABG & Electrolytes'),
(21, 'Respiratory Critical Care and Mechanical Ventilation', '20, PCO2 55 mm hg, PO2 65 mm hg, HCO3 22 m mol. What does this mean?', '["Respiratory acidosis", "Metabolic acidosis", "Metabolic alkalosis", "Respiratory alkalosis"]'::jsonb, 0, 'Acidic pH with elevated PCO2 and roughly normal HCO3 indicates respiratory acidosis.', 'Respiratory'),
(22, 'Respiratory Critical Care and Mechanical Ventilation', 'Which of the following mode of Mechanical Ventilation cannot be used for weaning off patients from Mechanical Ventilation:', '["Synchronized intermittent mandatory ventilation (SIMV)", "Pressure support ventilation (PSV)", "Controlled Mechanical ventilation (CMV)", "Assist-control ventilation (ACV)"]'::jsonb, 2, 'Fully controlled ventilation (CMV) gives no way to assess or build the patient''s own respiratory effort, so it can''t be used for weaning.', 'Respiratory'),
(23, 'Respiratory Critical Care and Mechanical Ventilation', 'The peak inspiratory pressure safety limit during mechanical ventilation for asthma is:', '["<20cmH2O", "<60cmH2O", "No limit needed", "<40cmH2O"]'::jsonb, 3, 'Exceeding this pressure risks rupturing the already overinflated, fragile lungs.', 'Respiratory'),
(24, 'Respiratory Critical Care and Mechanical Ventilation', 'Needle decompression for tension pneumothorax is performed at the:', '["2nd ICS posterior axillary line", "2nd ICS midclavicular line", "5th ICS anterior axillary line", "Xiphoid process"]'::jsonb, 1, 'This is the standard, quickest access point for emergency needle decompression before a formal chest tube can be placed.', 'Respiratory'),
(25, 'Respiratory Critical Care and Mechanical Ventilation', 'Which ventilator practice should be avoided in a hemodynamically unstable patient with status asthmaticus, due to risk of breath stacking?', '["Low tidal volume ventilation", "A permissive hypercapnia strategy", "Adequate sedation to reduce patient-ventilator dyssynchrony", "High respiratory rates with short expiratory time"]'::jsonb, 3, 'Rapid respiratory rates shorten expiratory time, which in severe bronchospasm causes incomplete exhalation, air trapping, auto-PEEP, and risk of barotrauma or hemodynamic collapse.', 'Respiratory'),
(26, 'Respiratory Critical Care and Mechanical Ventilation', 'A nurse is caring for a patient with a hemothorax. What is the most appropriate action if the patient''s chest tube drainage decreases significantly and the patient''s condition worsens?', '["Milk the tubing to dislodge the clot", "Notify the physician immediately", "Clamp the chest tube to prevent further drainage", "Increase the suction to the UWSD system"]'::jsonb, 1, 'A sudden decrease in drainage, coupled with a worsening patient condition, suggests that the chest tube may be occluded, leading to the re-accumulation of fluid in the chest. This is a medical emergency, and the physician must be notified immediately. Milking the tubing is generally discouraged as it can cause negative pressure damage to the lung tissue.', 'Respiratory'),
(27, 'Respiratory Critical Care and Mechanical Ventilation', 'How many bronchopulmonary segments does the right lung have?', '["12", "8", "6", "10"]'::jsonb, 3, 'The right lung has 3 lobes and 10 segments total (3 upper + 2 middle + 5 lower).', 'Respiratory'),
(28, 'Respiratory Critical Care and Mechanical Ventilation', 'A 40-year-old woman is involved in an equestrian accident. She presents with chest pain, shortness of breath, and difficulty breathing. Her arterial oxygen saturation is 85% and her respiratory rate is 40b/minute. A chest tube is placed and the nurse observes a return of 300 mls blood into the system. What is the nurse''s next line of action?', '["Explain to the patient what is going on to alley anxiety.", "Place the patient on oxygen.", "Clamp the tube and notify surgeon immediately.", "Call for a chest x-ray."]'::jsonb, 2, 'Sudden return of 300ml blood via the chest tube signals major haemorrhage — clamp and notify the surgeon immediately.', 'Respiratory'),
(29, 'Respiratory Critical Care and Mechanical Ventilation', 'A minimum respiratory rate of what value should be maintained during MgSO4 therapy?', '[">12/min", ">6/min", "No specific value is required", ">30/min"]'::jsonb, 0, 'A respiratory rate falling below this threshold suggests magnesium toxicity is depressing breathing.', 'Respiratory'),
(30, 'Respiratory Critical Care and Mechanical Ventilation', 'In metabolic acidosis, the expected respiratory compensation (fall in PaCO2) is calculated as:', '["2 × the pH change", "1.25 × the HCO3 fall", "0.1 × the HCO3 fall", "No compensation ever occurs"]'::jsonb, 1, 'The lungs blow off CO2 to help correct the acidosis, and this expected compensation follows this specific formula.', 'Respiratory'),
(31, 'Respiratory Critical Care and Mechanical Ventilation', 'ARDS in the context of orthopaedic trauma most often develops as a complication of:', '["Fat embolism or severe polytrauma", "Simple plaster cast application", "Isolated finger fractures", "Routine elective joint replacement with no complications"]'::jsonb, 0, 'Severe systemic insults like fat embolism or major polytrauma can trigger widespread lung inflammation, leading to ARDS.', 'Respiratory'),
(32, 'Respiratory Critical Care and Mechanical Ventilation', 'A nurse is assessing a patient with respiratory failure. The nurse notes that the patient''s respiratory rate is 35 breaths per minute. This is an example of:', '["Tachypnea", "Eupnea", "Bradypnea", "Apnea"]'::jsonb, 0, 'Tachypnea is an abnormally rapid respiratory rate, typically defined as more than 20 breaths per minute. The patient is breathing fast to compensate for the respiratory failure and try to improve gas exchange.', 'Respiratory'),
(33, 'Respiratory Critical Care and Mechanical Ventilation', 'This occurs when air enters the pleura but cannot escape, resulting in one-way valve effect, thus produces shift in the mediastinum.', '["Traumatic pneumothorax", "Tension pneumothorax", "Primary spontaneous pneumothorax", "Secondary spontaneous pneumothorax"]'::jsonb, 1, 'A one-way air-trapping valve effect with mediastinal shift is the hallmark of tension pneumothorax.', 'Respiratory'),
(34, 'Respiratory Critical Care and Mechanical Ventilation', 'During insertion of a subclavian central line for TPN, the patient suddenly develops sharp chest pain, dyspnea, and decreased breath sounds on the affected side. The nurse should suspect:', '["Catheter occlusion", "Pneumothorax", "Hyperglycemia", "Air embolism"]'::jsonb, 1, 'Pneumothorax is a recognized mechanical complication of subclavian or internal jugular central line placement, presenting with sudden chest pain, dyspnea, and diminished breath sounds on the affected side.', 'Respiratory'),
(35, 'Respiratory Critical Care and Mechanical Ventilation', 'A patient is receiving oxygen via a non-rebreather mask. The nurse notices the reservoir bag is completely deflating with each inspiration. The most appropriate nursing action is to:', '["Clamp the oxygen tubing", "Replace the mask with a simple face mask", "Loosen the mask to allow more room air to enter", "Increase the oxygen flow rate to the mask"]'::jsonb, 3, 'The reservoir bag of a non-rebreather mask should remain inflated on both inspiration and expiration to ensure a high FiO₂ is delivered. If it is deflating, the flow rate is too low and should be increased to maintain a high concentration of oxygen.', 'Respiratory'),
(36, 'Respiratory Critical Care and Mechanical Ventilation', 'A patient requires mechanical ventilation for airway protection due to a decreased level of consciousness (GCS 6) after a head injury. This is an example of which broad indication for ventilation?', '["Primary ventilatory (CO2) failure", "Inability to protect the airway", "Primary oxygenation failure", "Post-anesthesia recovery only"]'::jsonb, 1, 'A markedly depressed level of consciousness compromises airway reflexes, making inability to protect the airway a key indication for intubation and ventilation.', 'Respiratory'),
(37, 'Respiratory Critical Care and Mechanical Ventilation', 'During a spontaneous breathing trial, the rapid shallow breathing index (f/VT) that predicts weaning failure is above:', '["25 breaths/min/L", "50 breaths/min/L", "10 breaths/min/L", "105 breaths/min/L"]'::jsonb, 3, 'E.g. RR 35 with VT 0.25 L gives 140, so the trial is likely to fail.', 'Respiratory'),
(38, 'Respiratory Critical Care and Mechanical Ventilation', 'A ventilated patient suddenly desaturates. The ''DOPE'' mnemonic for the cause stands for:', '["Disconnection, Oxygen, PEEP, Exhaustion", "Drugs, Oxygen, Pressure, Electrolytes", "Dehydration, Oedema, Pneumonia, Embolism", "Displacement, Obstruction, Pneumothorax, Equipment failure"]'::jsonb, 3, 'Disconnect from the ventilator and hand-ventilate with 100% oxygen while checking each cause.', 'Respiratory'),
(39, 'Respiratory Critical Care and Mechanical Ventilation', 'Shortly after extubation a patient develops stridor. The first-line nursing treatment is:', '["Give oral antibiotics and observe for a day", "Deflate the cuff of the removed tube", "Sit upright, give oxygen and nebulised adrenaline", "Lie flat and give a large IV fluid bolus"]'::jsonb, 2, 'IV dexamethasone may also be ordered. Prepare for re-intubation if stridor worsens.', 'Respiratory'),
(40, 'Respiratory Critical Care and Mechanical Ventilation', 'In pressure-controlled ventilation, if lung compliance falls the nurse expects:', '["The respiratory rate to fall automatically", "Delivered tidal volume to rise automatically", "Delivered tidal volume to fall at the same set pressure", "Peak pressure to rise above the set level"]'::jsonb, 2, 'Pressure is fixed and volume varies, so the low tidal volume and minute volume alarms must be set carefully.', 'Respiratory'),
(41, 'Cardiovascular Critical Care and Haemodynamics', 'A woman with severe mitral stenosis and mitral regurgitation has a pulmonary artery catheter inserted. The physician orders pulmonary artery pressure monitoring, including pulmonary capillary wedge pressures. The purpose of this is to help assess the:', '["Peripheral arterial pressure.", "Pressure from fluid within the left ventricle.", "Degree of coronary artery stenosis.", "Oxygen and carbon dioxide concentration is the blood."]'::jsonb, 1, 'PCWP estimates left atrial pressure and so left ventricular filling (end-diastolic) pressure.', 'Cardiovascular'),
(42, 'Cardiovascular Critical Care and Haemodynamics', 'A patient has a PAWP of 22 mmHg, cardiac index of 1.8 L/min/m2, and elevated SVR. This hemodynamic profile is most consistent with:', '["Cardiogenic shock", "Distributive shock", "Hypovolemic shock", "Normal hemodynamics"]'::jsonb, 0, 'Elevated filling pressure (PAWP) with low cardiac index and compensatory vasoconstriction (high SVR) is the classic pattern of cardiogenic shock/pump failure.', 'Cardiovascular'),
(43, 'Cardiovascular Critical Care and Haemodynamics', 'A 2-year old was admitted for digoxin toxicity. BP is 94/60 mmhg, capillary refill time is 2 seconds and the ECG reveals 1st degree AV block with a heart rate of 60. The critical care nurse should:', '["Continue to monitor.", "Prepare for cardioversion.", "Administer atropine.", "Administer vasovagal maneuvers."]'::jsonb, 0, 'BP and cap refill are fine and 1st-degree block alone is benign — the correct action is simply to keep monitoring, not intervene.', 'Cardiovascular'),
(44, 'Cardiovascular Critical Care and Haemodynamics', 'Which ECG finding, though neither sensitive nor specific, is classically associated with acute PE and right heart strain?', '["Delta wave", "S1Q3T3 pattern", "Prolonged QT interval", "U waves"]'::jsonb, 1, 'The S1Q3T3 pattern (S wave in lead I, Q wave and inverted T wave in lead III) reflects acute right ventricular strain seen in some PE cases.', 'Cardiovascular'),
(45, 'Cardiovascular Critical Care and Haemodynamics', 'Which gas is used to inflate balloon during diastole in Intra-aortic Balloon pump (IABP) machine?', '["Helium", "Chlorine", "Iodine", "Hydrogen"]'::jsonb, 0, 'Helium is used because its low viscosity allows very rapid balloon inflation/deflation, and it''s safer if it embolises.', 'Cardiovascular'),
(46, 'Cardiovascular Critical Care and Haemodynamics', 'When is the use of spironolactone possibly contraindicated?', '["In patients with refractory congestive heart failure", "When also prescribing furosemide", "In hyperkalaemia patients", "In hypernatremia patients"]'::jsonb, 2, 'Spironolactone (a potassium-sparing diuretic) risks dangerous hyperkalaemia, so it is used cautiously in that setting.', 'Cardiovascular'),
(47, 'Cardiovascular Critical Care and Haemodynamics', 'Propranolol prophylaxis for variceal bleeding aims to reduce heart rate by approximately:', '["10% or to 90bpm", "25% or to 55bpm", "No specific target", "50% or to 40bpm"]'::jsonb, 1, 'This specific target reflects an adequate reduction in portal pressure achieved through beta-blockade.', 'Cardiovascular'),
(48, 'Cardiovascular Critical Care and Haemodynamics', 'On the day of surgery, a patient''s regular β-blocker medication should generally be:', '["Continued", "Stopped abruptly", "Doubled in dose", "Replaced with a diuretic"]'::jsonb, 0, 'Suddenly stopping a β-blocker can cause dangerous rebound effects, so it is continued through the perioperative period.', 'Cardiovascular'),
(49, 'Cardiovascular Critical Care and Haemodynamics', 'On the day of surgery, diuretics are generally:', '["Continued as normal", "Usually withheld", "Doubled in dose", "Given intravenously regardless of oral status"]'::jsonb, 1, 'Diuretics are typically held on the day of surgery to avoid compounding fluid shifts and electrolyte changes during the perioperative period.', 'Cardiovascular'),
(50, 'Cardiovascular Critical Care and Haemodynamics', 'Which of the following is NOT a reversible cause of Cardiac Arrest?', '["Hypoxia", "Hypovolemia", "Tension pneumothorax", "Hypertension"]'::jsonb, 3, 'Hypertension is not part of the reversible 4H/4T causes of arrest; the others (hypovolaemia, hypoxia, tension pneumothorax) are.', 'Cardiovascular'),
(51, 'Cardiovascular Critical Care and Haemodynamics', 'A patient with cirrhosis and a GI bleed carries higher rebleeding risk mainly because of:', '["Improved clotting function", "Lower blood pressure at baseline only", "No increased risk compared to others", "Portal hypertension and poor clotting"]'::jsonb, 3, 'Cirrhosis both raises pressure in the portal venous system (feeding varices) and impairs the liver''s ability to make clotting factors — a dangerous combination for rebleeding.', 'Cardiovascular'),
(52, 'Cardiovascular Critical Care and Haemodynamics', 'Rapid deflation of Balloon of IABP will decrease:', '["Contraction", "Pre-load", "Heart Rate", "After Load"]'::jsonb, 3, 'Rapid deflation just before systole reduces the resistance (afterload) the heart must pump against.', 'Cardiovascular'),
(53, 'Cardiovascular Critical Care and Haemodynamics', 'Elective surgery is generally considered for cancellation when blood pressure exceeds:', '["SBP >120 AND DBP >80", "SBP >180 AND DBP >110", "Any blood pressure above normal", "SBP >100 alone"]'::jsonb, 1, 'This combined threshold (or SBP ≥200 alone) reflects a level of risk considered too high for elective proceeding without first optimising blood pressure.', 'Cardiovascular'),
(54, 'Cardiovascular Critical Care and Haemodynamics', 'A nurse is assessing an electrocardiogram rhythm strip. The P waves and QRS complexes are regular. The PR interval is 0.16 second, and QRS complexes measure 0.06 second. The overall heart rate is 64 beats per minute. The nurse assesses the cardiac rhythm as:', '["Sinus bradycardia", "Sick sinus syndrome", "Normal sinus rhythm", "First-degree heart block"]'::jsonb, 2, 'Rate 64, regular, PR 0.16 s (normal 0.12–0.20) and QRS 0.06 s (under 0.12) is normal sinus rhythm.', 'Cardiovascular'),
(55, 'Cardiovascular Critical Care and Haemodynamics', 'A 50-year old man is admitted to the trauma resuscitation unit. He is intubated on arrival. What is the next step in the primary survey?', '["Obtain a chest x-ray to determine tube placement", "Initiate large-bore intravenous catheter placement and replace fluid.", "Assess the patient''s blood pressure and peripheral pulses.", "Listen to lung sounds to assess for ventilation."]'::jsonb, 3, 'After intubation, the immediate next step is confirming effective ventilation by auscultating breath sounds.', 'Cardiovascular'),
(56, 'Cardiovascular Critical Care and Haemodynamics', 'Which of the following should be the first monitor attached to the patient on arrival in the post anaesthesia care area (PACU):', '["Pulse oximeter", "Temperature monitoring device", "Non-invasive blood pressure", "Cardiac monitor"]'::jsonb, 3, 'Continuous cardiac monitoring is prioritised first on PACU arrival given arrhythmia risk post-anaesthesia.', 'Cardiovascular'),
(57, 'Cardiovascular Critical Care and Haemodynamics', 'With an intra-aortic balloon pump, the balloon should inflate at:', '["The upstroke of the arterial waveform", "The peak of the R wave on the ECG", "The start of atrial contraction (P wave)", "The dicrotic notch (aortic valve closure)"]'::jsonb, 3, 'Inflation in diastole improves coronary flow; deflation just before systole reduces afterload.', 'Cardiovascular'),
(58, 'Cardiovascular Critical Care and Haemodynamics', 'ST depression in V1–V3 with tall R waves in a patient with chest pain suggests:', '["Anterior wall ischaemia only", "Normal early repolarisation", "Posterior MI; record leads V7–V9", "Right bundle branch block only"]'::jsonb, 2, 'Posterior leads show ST elevation in a true posterior STEMI, which needs reperfusion.', 'Cardiovascular'),
(59, 'Cardiovascular Critical Care and Haemodynamics', 'The first-line drug for torsades de pointes with a pulse is:', '["IV adenosine 6 mg", "IV magnesium sulfate 2 g", "Oral digoxin 250 mcg", "IV amiodarone 900 mg"]'::jsonb, 1, 'Also stop QT-prolonging drugs and correct potassium. Pulseless torsades needs defibrillation.', 'Cardiovascular'),
(60, 'Cardiovascular Critical Care and Haemodynamics', 'Beck''s triad of cardiac tamponade is:', '["Hypotension, raised neck veins and muffled heart sounds", "Hypertension, bradycardia and irregular breathing", "Chest pain, ST elevation and raised troponin", "Fever, new murmur and splinter haemorrhages"]'::jsonb, 0, 'Treatment is urgent pericardiocentesis or surgical drainage.', 'Cardiovascular'),
(61, 'Neurological Critical Care', 'Which does NOT need to be excluded before testing for brain death?', '["Limb fractures", "Electrolyte imbalances", "Hypothermia", "Drug intoxication"]'::jsonb, 0, 'Before brainstem testing, exclude reversible causes: drugs and sedatives, hypothermia, and metabolic or electrolyte disturbances. Fractures do not affect the tests.', 'Neurology'),
(62, 'Neurological Critical Care', 'Bilateral damage to the spinal cord at the cervical level may produce:', '["monoplegia", "tetraplegia", "hemiplegia", "paraplegia"]'::jsonb, 1, 'Bilateral cervical cord damage affects all four limbs: tetraplegia (quadriplegia).', 'Neurology'),
(63, 'Neurological Critical Care', 'The nurse is providing skin care for an unconscious patient. What is the most effective intervention to prevent pressure ulcers?', '["Repositioning the patient every 2 hours", "Applying a thick layer of lotion to the skin", "Using a firm mattress on the bed", "Massaging reddened areas of the skin"]'::jsonb, 0, 'Frequent repositioning is the most effective way to prevent pressure ulcers. It relieves pressure on bony prominences and allows for proper blood flow to the skin. Massaging reddened areas can cause further damage, and a firm mattress is not ideal.', 'Neurology'),
(64, 'Neurological Critical Care', 'Central paresis and loss of proprioception on one side with loss of pain and temperature sensation on the opposite side form which syndrome?', '["Strümpell–Lorrain", "Argyll Robertson", "Brown-Séquard", "Lambert–Eaton"]'::jsonb, 2, 'Ipsilateral central paresis and proprioceptive loss with contralateral loss of pain and temperature is Brown-Séquard (cord hemisection) syndrome.', 'Neurology'),
(65, 'Neurological Critical Care', 'A nurse is positioning an unconscious patient. The patient''s head should be maintained in a:', '["Hyperextended position", "Flexed position on the chest", "Rotated position to the side", "Neutral, midline position"]'::jsonb, 3, 'Maintaining the head in a neutral, midline position helps to ensure venous drainage from the head, which can help to prevent an increase in intracranial pressure. Any flexion or rotation can impede blood flow.', 'Neurology'),
(66, 'Neurological Critical Care', 'If a patient continues seizing despite first- and second-line drugs, the next step generally involves:', '["Discharging the patient home", "Escalating to general anaesthesia/ICU-level care", "Simply waiting for the seizure to stop on its own", "No further treatment is available"]'::jsonb, 1, 'Refractory status epilepticus that hasn''t responded to standard drug therapy requires escalation to intensive, anaesthetic-level seizure control.', 'Neurology'),
(67, 'Neurological Critical Care', 'This disease condition consists of train of severe seizures with relatively short intervals or no interval between, the patient becomes exhausted and frequently hyperthermia. Death not uncommonly occurs during the attacks.', '["Persistent convulsion", "Poor epilepsy", "Status epilepticus", "Meningeal irritation"]'::jsonb, 0, 'Continuous seizures with exhaustion and hyperthermia describe status epilepticus.', 'Neurology'),
(68, 'Neurological Critical Care', 'The onset of delirium is usually rapid, within:', '["Months to years", "30 minutes to 1 hour", "Hours to a few days", "Weeks to months"]'::jsonb, 2, 'Delirium starts acutely, over hours to a few days, and fluctuates. Dementia develops over months to years.', 'Neurology'),
(69, 'Neurological Critical Care', 'A seizure that stops on its own after 3 minutes and the patient regains consciousness would be classified as:', '["Cannot be determined", "Epilepsy by definition", "Status epilepticus", "Not status epilepticus"]'::jsonb, 3, 'Since it resolved before the 5-minute threshold and the patient recovered consciousness, this does not meet the definition of status epilepticus.', 'Neurology'),
(70, 'Neurological Critical Care', 'The presence of dysphagia suggests damage to cranial nerves:', '["V-VII", "III-VI", "IX-X", "VII-XI"]'::jsonb, 2, 'The glossopharyngeal (IX) and vagus (X) nerves supply the pharynx and larynx, so damage causes dysphagia.', 'Neurology'),
(71, 'Neurological Critical Care', 'A nurse is caring for an unconscious patient. Which of the following is a priority nursing intervention to prevent complications?', '["Performing frequent oral care and airway suctioning", "Leaving the patient in the same position for extended periods", "Administering oral fluids every hour", "Encouraging the patient to cough and deep breathe"]'::jsonb, 0, 'Airway management is a priority for unconscious patients to prevent aspiration and maintain oxygenation. Oral care and suctioning are vital to remove secretions and maintain a patent airway. The other options are incorrect and potentially harmful.', 'Neurology'),
(72, 'Neurological Critical Care', 'Arranged from outermost to innermost, the correct order of the three meningeal layers surrounding the brain and spinal cord is', '["dura mater, pia mater, arachnoid mater", "arachnoid mater, dura mater, pia mater", "dura mater, arachnoid mater, pia mater", "pia mater, arachnoid mater, dura mater"]'::jsonb, 2, 'From outside in, the meninges are the dura mater (tough outer layer), arachnoid mater (middle, web-like layer), and pia mater (innermost, adheres directly to neural tissue).', 'Neurology'),
(73, 'Neurological Critical Care', 'Xanthochromia (yellow discoloration) of the cerebrospinal fluid on lumbar puncture is most suggestive of which condition?', '["Guillain-Barre syndrome", "Subarachnoid hemorrhage", "Normal CSF findings", "Bacterial meningitis only"]'::jsonb, 1, 'Xanthochromia results from the breakdown of red blood cells in the CSF and is a key finding supporting subarachnoid hemorrhage, especially when CT is negative but suspicion remains high.', 'Neurology'),
(74, 'Neurological Critical Care', 'What is the main target of neuromuscular blockers?', '["Motor end plate", "Synoptic vesicles", "Central nervous system (CNS)", "Muscle membrane"]'::jsonb, 0, 'The motor end plate (neuromuscular junction) is the primary target of these drugs.', 'Neurology'),
(75, 'Neurological Critical Care', 'When assessing the neurological status of an unconscious patient, which component of the Glasgow Coma Scale (GCS) is used to evaluate eye opening?', '["Eye Opening", "Pupillary Response", "Motor Response", "Verbal Response"]'::jsonb, 0, 'The GCS is a neurological scale that assesses a patient''s level of consciousness. The three main components are eye opening, verbal response, and motor response. Pupillary response is a separate neurological assessment.', 'Neurology'),
(76, 'Neurological Critical Care', 'An epidural hematoma classically results from injury to which structure, located in the potential space between the skull and the dura mater?', '["The superior sagittal sinus", "The internal carotid artery", "The middle meningeal artery", "A bridging vein"]'::jsonb, 2, 'Epidural hematomas are most often arterial, classically from laceration of the middle meningeal artery after temporal bone fracture, producing rapid hematoma expansion in the epidural (extradural) space.', 'Neurology'),
(77, 'Neurological Critical Care', 'In Guillain–Barré syndrome, elective intubation should be considered when vital capacity falls below:', '["50 mL/kg", "15–20 mL/kg", "70 mL/kg", "100 mL/kg"]'::jsonb, 1, 'Measure vital capacity regularly, because SpO₂ falls late. Watch for autonomic instability.', 'Neurology'),
(78, 'Neurological Critical Care', 'Which nursing measure helps reduce raised ICP in a ventilated head-injured patient?', '["Head flat with tight tube ties", "Head up 30°, neck midline, loose tube ties", "Frequent, long suction sessions", "Neck flexed down onto the chest"]'::jsonb, 1, 'Avoid jugular venous obstruction, hypoxia, hypercapnia, fever, and hypo- or hyperglycaemia.', 'Neurology'),
(79, 'Neurological Critical Care', 'For an external ventricular drain, the zero reference point is usually the:', '["Umbilicus with the patient flat", "Phlebostatic axis at the 4th intercostal space", "Tragus of the ear (level of the foramen of Monro)", "Sternal notch with the patient upright"]'::jsonb, 2, 'Clamp the drain before moving or repositioning the patient to avoid over-drainage.', 'Neurology'),
(80, 'Neurological Critical Care', 'A new unilateral fixed dilated pupil in a head-injured patient most likely indicates:', '["A normal pupil response to the bright pen torch", "Opioid toxicity, which affects both pupils equally", "Compression of cranial nerve III by uncal herniation on that side", "Optic nerve damage on the opposite side of the head"]'::jsonb, 2, 'This is a neurosurgical emergency: inform the team and prepare for CT and treatment.', 'Neurology'),
(81, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Which class of antibiotics is well known for nephrotoxic potential requiring renal dose adjustment and trough level monitoring in ICU patients?', '["Aminoglycosides", "First-generation cephalosporins", "Macrolides", "Penicillins"]'::jsonb, 0, 'Aminoglycosides such as gentamicin accumulate in proximal tubular cells and can cause dose-related acute tubular necrosis; trough levels and renal function must be monitored closely.', 'GI, Endocrine & Metabolic'),
(82, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Preoperative preparation for thyroidectomy includes administering Lugol''s iodine to:', '["Reduce laryngeal spasm", "Decrease gland vascularity", "Increase hormone release", "Induce euthyroid state"]'::jsonb, 1, 'Lugol''s iodine reduces the blood supply and firms up the gland, making surgery safer.', 'GI, Endocrine & Metabolic'),
(83, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A farmer presents with goitre and reports eating cassava regularly. Which mechanism explains his condition?', '["Cassava enhances thyroglobulin coupling", "Cassava reduces TRH secretion", "Cassava inhibits iodine trapping", "Cassava increases TSH secretion"]'::jsonb, 2, 'Cassava contains cyanogenic compounds that interfere with the thyroid''s ability to trap iodine.', 'GI, Endocrine & Metabolic'),
(84, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Chronic transplant rejection typically develops over:', '["Minutes to hours", "1–4 days", "Months to years", "Days to weeks"]'::jsonb, 2, 'Chronic rejection is a slow, multifactorial process that unfolds over a much longer timeframe than the other rejection types.', 'GI, Endocrine & Metabolic'),
(85, 'Renal, GI, Endocrine and Metabolic Critical Care', 'When administering a TPN solution, a nurse must verify that it contains all the prescribed components. What are the three main macronutrients provided in TPN?', '["Carbohydrates, proteins, and fats", "Sodium, potassium, and chloride", "Water, electrolytes, and vitamins", "Dextrose, amino acids, and lipids"]'::jsonb, 3, 'The three main macronutrient components of TPN are Dextrose (for carbohydrates), Amino Acids (for proteins), and Lipids (for fats). Water, electrolytes, and vitamins are also essential but are not considered macronutrients.', 'GI, Endocrine & Metabolic'),
(86, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Pre-operative anti-thyroid drug (ATD) treatment before thyroid surgery is typically given for:', '["1–2 years", "No pre-operative treatment is needed", "1–2 days", "4–6 weeks"]'::jsonb, 3, 'This preparation period helps bring thyroid hormone levels down to a safer level before the stress of surgery.', 'GI, Endocrine & Metabolic'),
(87, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A patient on TPN is showing signs of fluid volume excess. Which of the following nursing interventions is most appropriate?', '["Increasing the TPN infusion rate", "Monitoring the patient''s blood glucose levels", "Notifying the provider to decrease the fluid rate", "Administering a bolus of intravenous fluids"]'::jsonb, 2, 'If a patient shows signs of fluid volume excess (e.g., crackles, edema), the nurse should immediately notify the provider so the TPN infusion rate or the fluid components can be adjusted to prevent further complications like heart failure.', 'GI, Endocrine & Metabolic'),
(88, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A patient has an elevated TSH with a low free T4. This laboratory pattern is most consistent with which condition?', '["Primary hypothyroidism", "Secondary (central) hypothyroidism", "Subclinical hyperthyroidism", "Primary hyperthyroidism"]'::jsonb, 0, 'In primary hypothyroidism, the thyroid gland itself fails, so free T4 falls while the pituitary appropriately increases TSH in an attempt to stimulate the failing gland.', 'GI, Endocrine & Metabolic'),
(89, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A patient presents with palpitations, tremor, exophthalmos, and weight loss. The most probable diagnosis is:', '["Thyroid cyst", "Hashimoto''s disease", "Toxic goitre", "Simple goitre"]'::jsonb, 2, 'Palpitations, tremor, exophthalmos and weight loss together point to toxic (hyperfunctioning) goitre, classically Grave''s disease.', 'GI, Endocrine & Metabolic'),
(90, 'Renal, GI, Endocrine and Metabolic Critical Care', 'The most life-threatening intraoperative complication of thyroidectomy is:', '["Hemorrhage", "Hypocalcaemia", "Hoarseness", "Hypothyroidism"]'::jsonb, 0, 'Haemorrhage during thyroid surgery is life-threatening because of the gland''s rich blood supply and proximity to the airway.', 'GI, Endocrine & Metabolic'),
(91, 'Renal, GI, Endocrine and Metabolic Critical Care', 'During thyroid surgery, which structure must be preserved to prevent hypocalcaemia?', '["Submandibular duct", "Recurrent laryngeal nerve", "Carotid artery", "Parathyroid glands"]'::jsonb, 3, 'The parathyroid glands sit directly behind/within the thyroid and must be preserved to avoid post-op hypocalcaemia.', 'GI, Endocrine & Metabolic'),
(92, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Lugol''s iodine is used pre-operatively in thyroid surgery at a dose of:', '["It is not used pre-operatively", "50 drops for 1 day", "2–5 drops for 10–15 days", "1 drop for 1 year"]'::jsonb, 2, 'This short course helps reduce the vascularity and firm up the thyroid gland before surgery, making the operation safer.', 'GI, Endocrine & Metabolic'),
(93, 'Renal, GI, Endocrine and Metabolic Critical Care', 'The central control pathway for thyroid hormone production follows the sequence:', '["Thyroid → TSH → Pituitary → TRH → Hypothalamus", "Pituitary → Hypothalamus → TSH → TRH → Thyroid", "Hypothalamus → TRH → Pituitary → TSH → Thyroid", "TSH → Hypothalamus → TRH → Pituitary → Thyroid"]'::jsonb, 2, 'The hypothalamus releases TRH, which tells the pituitary to release TSH, which then stimulates the thyroid itself.', 'GI, Endocrine & Metabolic'),
(94, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A patient with fulminant hepatic failure develops worsening confusion and asterixis (flapping tremor). This presentation is most consistent with:', '["Hypoglycaemia unrelated to liver disease", "Simple fatigue", "A normal finding with no significance", "Hepatic encephalopathy"]'::jsonb, 3, 'Confusion with asterixis in a patient with liver failure is characteristic of hepatic encephalopathy, related to the liver''s reduced ability to clear ammonia.', 'GI, Endocrine & Metabolic'),
(95, 'Renal, GI, Endocrine and Metabolic Critical Care', 'To reduce aspiration risk during nasogastric tube feeding, the head of bed should be maintained at:', '["Prone position", "Flat, 0 degrees", "Elevated 30–45 degrees", "Trendelenburg position"]'::jsonb, 2, 'Elevating the head of bed 30–45 degrees during and after enteral feeding reduces the risk of gastric reflux and aspiration.', 'GI, Endocrine & Metabolic'),
(96, 'Renal, GI, Endocrine and Metabolic Critical Care', 'When giving lactulose for hepatic encephalopathy, the nurse aims for:', '["No stools to prevent fluid loss", "2–3 soft stools per day", "10 or more liquid stools daily", "One hard stool every 3 days"]'::jsonb, 1, 'Lactulose reduces ammonia absorption. Also look for triggers: bleeding, infection, constipation, sedatives.', 'GI, Endocrine & Metabolic'),
(97, 'Renal, GI, Endocrine and Metabolic Critical Care', 'The antidote for paracetamol (acetaminophen) overdose is:', '["IV flumazenil", "IV N-acetylcysteine", "IV naloxone", "IV protamine sulfate"]'::jsonb, 1, 'It is most effective within 8 hours. Use the treatment nomogram and monitor liver function and INR.', 'GI, Endocrine & Metabolic'),
(98, 'Renal, GI, Endocrine and Metabolic Critical Care', 'For septic shock that stays refractory despite fluids and vasopressors, guidelines suggest:', '["IV dexamethasone 40 mg as a single bolus", "Oral prednisolone 5 mg daily", "IV hydrocortisone about 200 mg per day", "IV methylprednisolone 1 g daily for 3 days"]'::jsonb, 2, 'Hydrocortisone shortens shock duration. Monitor glucose.', 'GI, Endocrine & Metabolic'),
(99, 'Renal, GI, Endocrine and Metabolic Critical Care', 'In thyroid storm, iodine (e.g. Lugol''s) should be given:', '["Instead of beta-blockers", "At least 1 hour after the antithyroid drug", "Only if the patient is hypothermic", "Before any antithyroid drug"]'::jsonb, 1, 'Antithyroid drugs block new hormone synthesis first. Iodine given first could fuel more hormone production.', 'GI, Endocrine & Metabolic'),
(100, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Treatment of myxoedema coma includes IV levothyroxine, IV hydrocortisone and:', '["Immediate propranolol infusion", "Strict fluid boluses of 5% dextrose", "Passive rewarming and support of breathing", "Rapid active external rewarming"]'::jsonb, 2, 'Give hydrocortisone until adrenal insufficiency is excluded. Active rewarming can cause vasodilatory collapse.', 'GI, Endocrine & Metabolic'),
(101, 'Shock, Trauma, Burns and Emergencies', 'A patient with a high spinal cord injury develops hypotension WITH bradycardia (rather than the expected compensatory tachycardia). This is most consistent with:', '["Hypovolaemic shock", "Cardiogenic shock", "Septic shock", "Neurogenic shock"]'::jsonb, 3, 'Neurogenic shock, from disrupted sympathetic tone after high spinal cord injury, is distinguished by hypotension with bradycardia rather than the tachycardia seen in most other shock types.', 'Shock & Haemorrhage'),
(102, 'Shock, Trauma, Burns and Emergencies', 'A widened mediastinum after chest trauma raises suspicion of:', '["Simple rib fracture", "Normal anatomical variant", "Minor bruising only", "Thoracic aortic disruption"]'::jsonb, 3, 'This is considered the most important X-ray warning sign for a potentially fatal aortic tear after trauma.', 'Shock & Haemorrhage'),
(103, 'Shock, Trauma, Burns and Emergencies', 'A patient with a spinal cord injury above T6 develops sudden severe hypertension, a pounding headache, bradycardia, and flushing above the level of injury after the bladder becomes distended. Which NANDA-I diagnosis best matches this presentation?', '["Autonomic Dysreflexia", "Risk for Autonomic Dysreflexia", "Ineffective Cerebral Tissue Perfusion", "Decreased Cardiac Output"]'::jsonb, 0, 'Autonomic Dysreflexia (the actual diagnosis, since symptoms are already present) is triggered by a noxious stimulus such as bladder distension in patients with spinal cord injury at or above T6, producing paroxysmal hypertension, bradycardia, headache, and flushing.', 'Shock & Haemorrhage'),
(104, 'Shock, Trauma, Burns and Emergencies', 'For small or patchy burns, a quick estimate of surface area can be made using:', '["No estimation method exists", "The patient''s own palm ≈ 1% TBSA", "Lund and Browder chart only in adults", "The Rule of Nines only"]'::jsonb, 1, 'The palm method is a convenient bedside estimate: the patient''s own palm (including fingers) is roughly equal to 1% of their total body surface area.', 'Shock & Haemorrhage'),
(105, 'Shock, Trauma, Burns and Emergencies', 'A 24 year old male is presented to ER with head injury. The patient has Tracheostomy intact. Heart Rate is below 50/min.Physician advised to administer Atropine 1 mg immediately. The only route of administering medication is Trachea now. Along with Atropine what other medications can be administered through Trachea;', '["Adrenaline", "Calcium", "NaHCO3", "Amiodarone,"]'::jsonb, 0, 'Endotracheal drugs follow "NAVEL" — adrenaline (epinephrine) can be given via the ET route along with atropine.', 'Shock & Haemorrhage'),
(106, 'Shock, Trauma, Burns and Emergencies', 'Compartment syndrome causing pain on passive stretch of the affected muscle is significant because it is:', '["Only seen after the compartment has already been decompressed", "Never associated with compartment syndrome", "A late, unreliable sign", "Often one of the earliest warning signs"]'::jsonb, 3, 'Pain that is disproportionate to the injury, especially when a muscle is passively stretched, is often the earliest clue that compartment pressure is dangerously high, before pulses are even lost.', 'Shock & Haemorrhage'),
(107, 'Shock, Trauma, Burns and Emergencies', 'The overarching principle guiding resource allocation in a mass casualty disaster response is:', '["Achieve the greatest good for the greatest number of casualties", "Treat the most severely injured patient first no matter what", "Treat only patients who can pay for care", "Treat whoever arrived first, regardless of severity"]'::jsonb, 0, 'Disaster triage is guided by achieving the greatest good for the greatest number, which sometimes means the most critically injured (unsalvageable) casualties are deprioritised in favour of those with a realistic chance of survival.', 'Shock & Haemorrhage'),
(108, 'Shock, Trauma, Burns and Emergencies', 'The critical care nurse knows simultaneous injury of different regions of the body of which one or the combination of these injuries is life threatening, is popularly known as:', '["Very severe trauma", "Polytrauma", "Poly head injuries", "Severe multiple injuries"]'::jsonb, 1, 'Simultaneous life-threatening injuries across multiple body regions is the definition of polytrauma.', 'Shock & Haemorrhage'),
(109, 'Shock, Trauma, Burns and Emergencies', 'The correct first aid for a chemical burn is:', '["Apply a neutralising agent immediately", "Apply ice directly", "Cover with a dry dressing only", "Copious irrigation with water"]'::jsonb, 3, 'Water dilutes and washes away the chemical; neutralisers generate extra heat and worsen the burn.', 'Shock & Haemorrhage'),
(110, 'Shock, Trauma, Burns and Emergencies', 'Voltage above what threshold is classified as ''high voltage'' in electrical burns?', '["10,000V", "100V", "1000V", "100,000V"]'::jsonb, 2, 'Voltage above 1000V is classified as high voltage, with a very different injury pattern (deep, deceptive tissue damage) compared to low voltage.', 'Shock & Haemorrhage'),
(111, 'Shock, Trauma, Burns and Emergencies', 'A prolonged capillary refill time (greater than 2–3 seconds) in a shocked patient suggests:', '["Adequate peripheral perfusion", "Only a cold ambient room temperature, never clinical significance", "Improved cardiac output", "Reduced peripheral perfusion"]'::jsonb, 3, 'Delayed capillary refill reflects peripheral vasoconstriction and reduced perfusion, a simple bedside sign consistent with shock states, though ambient temperature can also affect it.', 'Shock & Haemorrhage'),
(112, 'Shock, Trauma, Burns and Emergencies', 'Because of extensive skin loss, TENS patients are managed most similarly to which other critical care population?', '["Uncomplicated cellulitis patients", "Major burn patients", "Stable post-operative orthopedic patients", "Chronic wound outpatients"]'::jsonb, 1, 'The extensive skin loss, fluid shifts, and infection risk in TENS closely parallel major burn injury, so patients are often managed in a burn unit using burn-care principles.', 'Shock & Haemorrhage'),
(113, 'Shock, Trauma, Burns and Emergencies', 'A 30 years old male admitted to ICU with RTA (road traffic accident), she is unconscious and is on ventilator with Tidal volume=550 and FiO2=90%. She has CVP line inserted because of failure to insert I/V cannula, IV bolus of 1 litre and blood was infused. You are measuring his CVP which is 12cm of H2O, what does this indicate?', '["Normal volume", "Hypovolemia", "Mixed state", "Hypervolemia"]'::jsonb, 3, 'CVP of 12 (above the normal 2-8 range) indicates volume overload — hypervolaemia.', 'Shock & Haemorrhage'),
(114, 'Shock, Trauma, Burns and Emergencies', 'A 30-year-old man with a stab wound to the neck is alert but bleeding actively in the resuscitation bay. You should first:', '["Locally explore the wound to find the bleeding point", "Clamp the bleeding vessels blindly", "Place two large-bore IV cannulae and give O-negative blood", "Apply direct pressure to the site"]'::jsonb, 3, 'Control external haemorrhage from a neck wound with direct pressure. Never clamp blindly or probe the wound in the resuscitation bay; the patient needs surgical exploration.', 'Shock & Haemorrhage'),
(115, 'Shock, Trauma, Burns and Emergencies', 'For monitoring global perfusion, venous oxygen saturation is NOT reliably measured from a:', '["Central venous catheter in the superior vena cava", "Pulmonary artery catheter", "Femoral venous catheter", "Continuous oximetric central catheter"]'::jsonb, 2, 'Femoral venous saturation reflects only the legs. Global ScvO2 is sampled from the SVC (central line) or pulmonary artery (SvO2).', 'Shock & Haemorrhage'),
(116, 'Shock, Trauma, Burns and Emergencies', 'A patient with carbon monoxide poisoning from smoke inhalation should be treated with:', '["IV antibiotics as the primary treatment", "Room air only", "No oxygen therapy is needed", "Humidified 100% oxygen"]'::jsonb, 3, 'CO binds haemoglobin far more strongly than oxygen — humidified 100% oxygen displaces CO from haemoglobin and is the mainstay treatment for CO poisoning.', 'Shock & Haemorrhage'),
(117, 'Shock, Trauma, Burns and Emergencies', 'After a high-voltage electrical burn with dark red urine, the target urine output is about:', '["5 mL/kg/h using diuretics only", "1–1.5 mL/kg/h until the urine clears", "0.1 mL/kg/h to protect the kidneys", "0.3 mL/kg/h with fluid restriction"]'::jsonb, 1, 'Myoglobin can cause acute kidney injury. Also monitor ECG and compartments.', 'Shock & Haemorrhage'),
(118, 'Shock, Trauma, Burns and Emergencies', 'Adult anaphylaxis is first treated with IM adrenaline at a dose of:', '["5 mg (5 mL of 1:1000) IV push", "1 mg (10 mL of 1:10,000) intramuscularly in the deltoid", "0.05 mg (0.5 mL of 1:10,000) subcutaneously", "0.5 mg (0.5 mL of 1:1000) into the anterolateral thigh"]'::jsonb, 3, 'Repeat after 5 minutes if there is no improvement. Then give oxygen, fluids and call for help.', 'Shock & Haemorrhage'),
(119, 'Shock, Trauma, Burns and Emergencies', 'The current ATLS site for needle decompression of tension pneumothorax in adults is:', '["4th–5th intercostal space, anterior to mid-axillary line", "Just above the umbilicus", "2nd intercostal space in the lateral chest", "7th intercostal space, posterior axillary line"]'::jsonb, 0, 'Chest wall thickness makes the 2nd ICS mid-clavicular site fail more often. A chest drain follows.', 'Shock & Haemorrhage'),
(120, 'Shock, Trauma, Burns and Emergencies', 'A FAST ultrasound scan in trauma looks for free fluid in the pericardium, right and left upper quadrants and:', '["Thyroid", "Pelvis", "Spinal canal", "Brain"]'::jsonb, 1, 'A positive FAST in an unstable patient usually means theatre.', 'Shock & Haemorrhage'),
(121, 'Obstetric, Neonatal and Paediatric Critical Care', 'A pregnant patient presents with severe, constant abdominal pain, a tense/rigid uterus, and dark vaginal bleeding. This presentation is most concerning for:', '["Normal labour onset", "Placenta praevia", "Braxton Hicks contractions", "Placental abruption"]'::jsonb, 3, 'Painful bleeding with uterine rigidity/tenderness is characteristic of placental abruption, an obstetric emergency threatening both mother and fetus.', 'Obstetric & Neonatal'),
(122, 'Obstetric, Neonatal and Paediatric Critical Care', 'The compression depth recommended for an infant during CPR is approximately:', '["5–6cm", "1cm", "8cm", "4cm"]'::jsonb, 3, 'An infant''s chest is much smaller and more fragile, so the target compression depth is shallower, at about 4cm, compared to 5–6cm in an adult.', 'Obstetric & Neonatal'),
(123, 'Obstetric, Neonatal and Paediatric Critical Care', 'Rh incompatibility is of particular clinical concern in pregnancy when:', '["The mother is blood type O", "An Rh-positive mother carries an Rh-negative fetus", "An Rh-negative mother carries an Rh-positive fetus", "Both parents are Rh-negative"]'::jsonb, 2, 'An Rh-negative mother sensitised to Rh-positive fetal blood (often from a prior pregnancy) can develop antibodies that cross the placenta and cause haemolytic disease in a subsequent Rh-positive fetus.', 'Obstetric & Neonatal'),
(124, 'Obstetric, Neonatal and Paediatric Critical Care', 'MEOWS stands for:', '["Maternal Early Warning Signs", "Modified Early Obstetric Warning Score", "Modified Early Obstetric Warning Signs", "Moment Evaluation of Obstetric Syndrome"]'::jsonb, 1, 'MEOWS is the Modified Early Obstetric Warning Score, used to detect deterioration in pregnant and postnatal women.', 'Obstetric & Neonatal'),
(125, 'Obstetric, Neonatal and Paediatric Critical Care', 'Which of the following is not an obstetric cause of disseminated intravascular coagulopathy;', '["Pre-eclampsia/eclampsia", "Amniotic fluid embolism", "Abruptio placentae", "Uterine inversion"]'::jsonb, 3, 'Obstetric causes of DIC include abruption, amniotic fluid embolism, pre-eclampsia/HELLP and sepsis. Uterine inversion causes haemorrhage and shock rather than DIC.', 'Obstetric & Neonatal'),
(126, 'Obstetric, Neonatal and Paediatric Critical Care', 'An acute event involving the cardiorespiratory and/or central nervous system that causes reduced or absent consciousness in pregnancy is:', '["Ectopic pregnancy", "Placenta praevia", "Maternal collapse", "Hyperemesis gravidarum"]'::jsonb, 2, 'Maternal collapse is an acute cardiorespiratory and/or CNS event causing reduced or absent consciousness, at any stage of pregnancy up to 6 weeks after delivery.', 'Obstetric & Neonatal'),
(127, 'Obstetric, Neonatal and Paediatric Critical Care', 'A 35year old para 7+2 [6alive] ,just had a spontaneous vaginal delivery of a live baby boy, she is lying on bed not talking, on examination her pulse rate is 100b/m, blood pressure 50/?, the possible cause is: ___________', '["Inadequate history during antenatal booking", "Inadequate history of onset of labor", "Not regular in antenatal visit prenatally", "Thromboembolism"]'::jsonb, 3, 'Persistent hypotension/tachycardia postpartum with unclear labour history raises suspicion for occult bleeding tied to inadequate labour monitoring/history.', 'Obstetric & Neonatal'),
(128, 'Obstetric, Neonatal and Paediatric Critical Care', 'The commonest surgical procedure used to treat ruptured tubal pregnancy is', '["Salpingectomy", "Salpingo-oophorectomy", "Total hysterectomy", "oophorectomy"]'::jsonb, 0, 'Salpingectomy (removal of the affected tube) is the standard surgery for a ruptured tubal pregnancy.', 'Obstetric & Neonatal'),
(129, 'Obstetric, Neonatal and Paediatric Critical Care', 'Which drug is contraindicated for controlling postpartum bleeding in a woman with eclampsia?', '["Carboprost", "Ergometrine", "Misoprostol", "Oxytocin"]'::jsonb, 1, 'Ergometrine causes vasoconstriction that can dangerously raise already-high blood pressure.', 'Obstetric & Neonatal'),
(130, 'Obstetric, Neonatal and Paediatric Critical Care', 'A child weighing 18 kg is prescribed an antibiotic at 10 mg/kg/day divided every 8 hours. How many milligrams should be given per dose?', '["60 mg", "180 mg", "30 mg", "90 mg"]'::jsonb, 0, 'Total daily dose = 18 kg x 10 mg/kg = 180 mg/day. Divided every 8 hours = 3 doses/day, so 180/3 = 60 mg/dose.', 'Obstetric & Neonatal'),
(131, 'Obstetric, Neonatal and Paediatric Critical Care', 'Which statement about pre-eclampsia is correct?', '["It is mainly a disease of primigravidae", "BP >140/110 defines severe disease", "MgSO4 is used to lower blood pressure in emergencies", "Oedema is required for diagnosis"]'::jsonb, 0, 'Pre-eclampsia is mainly a disease of first pregnancies (primigravidae). Oedema is no longer diagnostic; MgSO4 prevents fits but does not treat BP.', 'Obstetric & Neonatal'),
(132, 'Obstetric, Neonatal and Paediatric Critical Care', 'Common causes of antepartum haemorrhage from 24 weeks'' gestation include which of the following?', '["Uterine rupture", "placenta praevia", "Placenta abruption", "Normal period"]'::jsonb, 1, 'Placenta praevia is a leading recognised cause of antepartum haemorrhage from 24 weeks onward.', 'Obstetric & Neonatal'),
(133, 'Obstetric, Neonatal and Paediatric Critical Care', 'A child in septic shock needs a fluid bolus of:', '["100 mL/kg of 5% dextrose quickly", "1 mL/kg of blood only", "50 mL/kg of 0.18% saline", "10 mL/kg of crystalloid, then reassess"]'::jsonb, 3, 'Reassess after each bolus for signs of fluid overload (liver edge, crackles).', 'Obstetric & Neonatal'),
(134, 'Obstetric, Neonatal and Paediatric Critical Care', 'The defibrillation energy for a child in VF is:', '["360 J for all ages", "40 J/kg", "0.4 J/kg", "4 J/kg"]'::jsonb, 3, 'Then resume CPR immediately for 2 minutes.', 'Obstetric & Neonatal'),
(135, 'Obstetric, Neonatal and Paediatric Critical Care', 'The IV adrenaline dose in paediatric cardiac arrest is:', '["1 mg/kg (10 mL/kg of 1:10,000)", "0.1 mcg/kg (0.001 mL/kg of 1:1000)", "10 mcg/kg (0.1 mL/kg of 1:10,000)", "100 mcg/kg (1 mL/kg of 1:1000)"]'::jsonb, 2, 'Repeat every 3–5 minutes.', 'Obstetric & Neonatal'),
(136, 'Obstetric, Neonatal and Paediatric Critical Care', 'For a 4-year-old, the uncuffed endotracheal tube size (age ÷ 4 + 4) is:', '["3.0 mm internal diameter", "8.0 mm internal diameter", "7.5 mm internal diameter", "5.0 mm internal diameter"]'::jsonb, 3, 'For cuffed tubes use age ÷ 4 + 3.5. Tube length (oral) is about age ÷ 2 + 12 cm.', 'Obstetric & Neonatal'),
(137, 'Obstetric, Neonatal and Paediatric Critical Care', 'In children aged 1–10 years, hypotension is a systolic BP below:', '["100 + (age in years) mmHg", "70 + (2 × age in years) mmHg", "50 mmHg at any age", "90 mmHg at any age"]'::jsonb, 1, 'Hypotension is a late sign of shock in children; tachycardia and poor perfusion come first.', 'Obstetric & Neonatal'),
(138, 'Obstetric, Neonatal and Paediatric Critical Care', 'A child with croup has stridor at rest. The nurse expects:', '["Throat swab and oral antibiotics only", "Immediate chest physiotherapy", "Nebulised salbutamol alone", "Oral dexamethasone and nebulised adrenaline"]'::jsonb, 3, 'Keep the child calm and on the parent''s lap.', 'Obstetric & Neonatal'),
(139, 'Obstetric, Neonatal and Paediatric Critical Care', 'A drooling, toxic-looking child sitting forward with stridor may have epiglottitis. The nurse should:', '["Keep the child calm and upright and not examine the throat", "Lie the child flat and inspect the throat", "Take all blood samples first, then act", "Give a sedative to stop the child crying"]'::jsonb, 0, 'Upsetting the child can cause complete airway obstruction. The airway is secured by an expert, often in theatre.', 'Obstetric & Neonatal'),
(140, 'Obstetric, Neonatal and Paediatric Critical Care', 'Children in DKA are at risk of cerebral oedema, so management includes:', '["An insulin bolus of 1 unit/kg at the start", "Hypotonic fluid to correct sodium quickly", "Slow fluid replacement over 48 hours and no insulin bolus", "Rapid 20 mL/kg fluid boluses repeated hourly"]'::jsonb, 2, 'Report headache, falling heart rate or confusion at once.', 'Obstetric & Neonatal'),
(141, 'ICU Pharmacology and Anaesthesia', 'The specific antidote for opioid overdose (e.g. morphine, fentanyl) is:', '["N-acetylcysteine", "Naloxone", "Activated charcoal", "Flumazenil"]'::jsonb, 1, 'Naloxone is a competitive opioid receptor antagonist used to reverse opioid-induced respiratory depression.', 'ICU Pharmacology'),
(142, 'ICU Pharmacology and Anaesthesia', 'Zopiclone, a cyclopyrrolone-class Z-drug similar to zolpidem, is particularly associated with which distinctive adverse effect?', '["Serotonin syndrome", "A metallic or bitter taste after use", "Severe hepatotoxicity in most patients", "Malignant hyperthermia"]'::jsonb, 1, 'Zopiclone is well known for causing a distinctive metallic or bitter aftertaste, in addition to typical Z-drug effects such as next-day sedation.', 'ICU Pharmacology'),
(143, 'ICU Pharmacology and Anaesthesia', 'A patient presents with pinpoint pupils, respiratory rate of 6 breaths/min, decreased level of consciousness, and bradycardia. Which toxidrome does this most likely represent?', '["Cholinergic toxidrome", "Anticholinergic toxidrome", "Opioid toxidrome", "Sympathomimetic toxidrome"]'::jsonb, 2, 'Miosis (pinpoint pupils), respiratory depression, and CNS depression are the classic triad of opioid toxicity.', 'ICU Pharmacology'),
(144, 'ICU Pharmacology and Anaesthesia', 'The concentration of epinephrine used for endoscopic injection in bleeding ulcers is:', '["1:1,000,000", "1:100,000", "1:10,000", "1:1,000"]'::jsonb, 2, 'This diluted concentration is strong enough to cause local vasoconstriction and stop bleeding without excessive systemic effect.', 'ICU Pharmacology'),
(145, 'ICU Pharmacology and Anaesthesia', 'Which volatile anaesthetic agent is most associated with sensitizing the myocardium to catecholamines, predisposing to arrhythmias, particularly if epinephrine is administered concurrently?', '["Halothane", "Sevoflurane", "Nitrous oxide", "Desflurane"]'::jsonb, 0, 'Halothane sensitizes the myocardium to circulating catecholamines more than other modern volatile agents, increasing the risk of ventricular arrhythmias when epinephrine-containing solutions are used.', 'ICU Pharmacology'),
(146, 'ICU Pharmacology and Anaesthesia', 'Which class of immunosuppressant medications, including tacrolimus and cyclosporine, inhibits calcineurin to reduce T-cell activation but carries a significant risk of nephrotoxicity?', '["Induction antibody agents", "Corticosteroids", "Calcineurin inhibitors", "Antimetabolites, such as mycophenolate"]'::jsonb, 2, 'Calcineurin inhibitors such as tacrolimus and cyclosporine block T-cell activation by inhibiting calcineurin-dependent IL-2 production, but are also directly nephrotoxic and require careful therapeutic drug monitoring to balance rejection prevention with drug-induced kidney injury.', 'ICU Pharmacology'),
(147, 'ICU Pharmacology and Anaesthesia', 'A patient on fentanyl PCA has a respiratory rate of 8/min and is somnolent. Which antidote should the nurse administer?', '["Romazicon", "Flumazenil", "Naloxone", "Physostigmine"]'::jsonb, 2, 'Naloxone reverses opioid-induced respiratory depression. Flumazenil reverses benzodiazepines.', 'ICU Pharmacology'),
(148, 'ICU Pharmacology and Anaesthesia', 'The pharmacy needs 500 mL of a 5% dextrose solution but only has 50% dextrose stock solution and sterile water available. How much of the 50% stock solution is needed?', '["50 mL of stock, diluted with 450 mL water", "100 mL of stock, diluted with 400 mL water", "250 mL of stock, diluted with 250 mL water", "5 mL of stock, diluted with 495 mL water"]'::jsonb, 0, 'Using C1V1 = C2V2: 50% x V1 = 5% x 500 mL, so V1 = 2500/50 = 50 mL of stock, topped up with 450 mL diluent to make 500 mL.', 'ICU Pharmacology'),
(149, 'ICU Pharmacology and Anaesthesia', 'A nurse must give a 40 mg IV push dose over 4 minutes. The drug is supplied as 40 mg in 4 mL. At what rate, in mL/min, should the nurse push the medication?', '["10 mL/min", "1 mL/min", "0.5 mL/min", "4 mL/min"]'::jsonb, 1, 'Concentration = 40 mg/4 mL = 10 mg/mL. To deliver 40 mg over 4 minutes = 10 mg/min = 1 mL/min.', 'ICU Pharmacology'),
(150, 'ICU Pharmacology and Anaesthesia', 'A patient taking ibuprofen 400 mg twice daily for chronic back pain develops leg oedema. This is most likely caused by:', '["A low creatinine level", "A decrease in renal function", "An increase in plasma proteins", "An increased glomerular filtration rate"]'::jsonb, 1, 'NSAIDs block renal prostaglandins, reducing renal blood flow and GFR and causing sodium and water retention and oedema.', 'ICU Pharmacology'),
(151, 'ICU Pharmacology and Anaesthesia', 'Compared with the other agents listed, which is most likely to cause direct, dose-dependent myocardial contractile depression rather than predominantly vasodilation?', '["Isoflurane", "Halothane", "Desflurane", "Sevoflurane at low concentrations"]'::jsonb, 1, 'Halothane depresses myocardial contractility more directly than isoflurane, desflurane, or sevoflurane, which cause relatively more vasodilation with better-preserved cardiac output at equivalent MAC.', 'ICU Pharmacology'),
(152, 'ICU Pharmacology and Anaesthesia', 'A patient with myasthenia gravis is prescribed neostigmine. The nurse should monitor for:', '["Cholinergic crisis", "Neuroleptic malignant syndrome", "Thyroid storm", "Serotonin syndrome"]'::jsonb, 0, 'Overdose of acetylcholinesterase inhibitors (e.g., neostigmine) causes cholinergic crisis (SLUDGE syndrome).', 'ICU Pharmacology'),
(153, 'ICU Pharmacology and Anaesthesia', 'A thyroidectomy patient complains of palpitations and anxiety preoperatively. The nurse should administer:', '["Propanolol", "Dopamine", "Adrenaline", "Morphine"]'::jsonb, 0, 'Propranolol controls the adrenaline-driven symptoms (palpitations, anxiety, tremor) of residual hyperthyroidism.', 'ICU Pharmacology'),
(154, 'ICU Pharmacology and Anaesthesia', 'Which of the following is not an ideal characteristic of a volatile anaesthetic agent?', '["Odourless or pleasant to inhale", "Cheap to manufacture", "Flammable", "Safe for all ages and in pregnancy"]'::jsonb, 2, 'Flammability is a dangerous, undesirable property — not an ideal characteristic of a volatile anaesthetic.', 'ICU Pharmacology'),
(155, 'ICU Pharmacology and Anaesthesia', 'The concentration of inhalational anaesthetic at which a patient responds purposefully to verbal command during emergence is referred to as:', '["MAC95", "MAC-awake", "Blood-gas MAC", "MAC-BAR"]'::jsonb, 1, 'MAC-awake, typically about 0.3-0.5 of standard MAC, is the concentration at which patients begin to respond to verbal commands as anaesthesia lightens.', 'ICU Pharmacology'),
(156, 'ICU Pharmacology and Anaesthesia', 'A patient on dopamine at 15 mcg/kg/min is likely to experience:', '["Vasoconstriction", "Bronchospasm", "Renal artery dilation", "Hyperglycemia"]'::jsonb, 0, 'High-dose dopamine (>10 mcg/kg/min) activates α-receptors, causing vasoconstriction.', 'ICU Pharmacology'),
(157, 'ICU Pharmacology and Anaesthesia', 'Rocuronium-induced neuromuscular block can be rapidly reversed by:', '["Neostigmine alone at any depth of block", "Suxamethonium", "Dantrolene", "Sugammadex"]'::jsonb, 3, 'Sugammadex binds rocuronium directly. Neostigmine works only for shallow block and is given with glycopyrrolate.', 'ICU Pharmacology'),
(158, 'ICU Pharmacology and Anaesthesia', 'A patient on heparin has platelets falling by more than 50% with new thrombosis. The nurse expects to:', '["Give a platelet transfusion and keep the heparin", "Switch to low molecular weight heparin injections", "Increase the heparin dose to treat the new clot", "Stop all heparin, including flushes, and start a non-heparin anticoagulant"]'::jsonb, 3, 'Heparin-induced thrombocytopenia causes clots, not bleeding. Argatroban or fondaparinux are alternatives.', 'ICU Pharmacology'),
(159, 'ICU Pharmacology and Anaesthesia', 'In shockable cardiac arrest, the first dose of amiodarone is:', '["50 mg IV after every shock", "900 mg IV after the first shock", "300 mg IV after the third shock", "150 mg IV before the first shock"]'::jsonb, 2, 'A further 150 mg may be given after the fifth shock.', 'ICU Pharmacology'),
(160, 'ICU Pharmacology and Anaesthesia', 'Once-daily dosing of gentamicin is used because aminoglycosides:', '["Are not toxic to the kidney or ear", "Kill bacteria in a concentration-dependent way", "Are best given as a continuous infusion", "Kill bacteria in a time-dependent way only"]'::jsonb, 1, 'High peaks kill bacteria, and low troughs reduce nephrotoxicity and ototoxicity.', 'ICU Pharmacology'),
(161, 'ICU Management, Ethics and Law', 'A nursing manager is using a concurrent audit to identify potential issues with patient care. The advantage of a concurrent audit is that it allows for:', '["The collection of a large amount of data from many patients at once", "Immediate intervention to correct a problem", "A review of care after the patient has been discharged", "A historical analysis of care over a long period"]'::jsonb, 1, 'Since a concurrent audit is performed while the patient is still receiving care, it provides an opportunity to identify and address issues in real time, preventing a poor outcome or improving the quality of care on the spot.', 'Ethics, Law & Management'),
(162, 'ICU Management, Ethics and Law', 'A ward sister reviews a currently admitted patient''s chart mid-treatment to check whether nursing care so far meets set standards, allowing immediate correction if needed. This exemplifies:', '["Retrospective audit", "Risk transfer", "Sentinel event review", "Concurrent audit"]'::jsonb, 3, 'Reviewing an active patient''s ongoing care to enable real-time correction is the hallmark of concurrent audit.', 'Ethics, Law & Management'),
(163, 'ICU Management, Ethics and Law', 'He was the first to systematically describe management behaviour and also pioneered the identification of the principles and skills that underlie effective management.', '["Henri Fayol", "F. Taylor", "Max waber", "Gashinge et all."]'::jsonb, 0, 'Henri Fayol is credited as the pioneer of systematic management theory and principles.', 'Ethics, Law & Management'),
(164, 'ICU Management, Ethics and Law', 'Which leadership style is most appropriate during cardiopulmonary resuscitation?', '["Laissez-faire", "Transformational", "Democratic", "Autocratic"]'::jsonb, 3, 'During CPR, clear, rapid, directive instructions from one leader are needed, making autocratic leadership most appropriate in that emergency moment.', 'Ethics, Law & Management'),
(165, 'ICU Management, Ethics and Law', 'A competent patient''s living will refuses aggressive cancer treatment, but the physician insists on chemotherapy for the patient''s benefit. The physician is exercising:', '["Veracity", "Paternalism", "Ideal beneficence", "Respect for autonomy"]'::jsonb, 1, 'Paternalism is overriding a competent patient''s known wishes (such as a living will refusing aggressive treatment) "for their own good".', 'Ethics, Law & Management'),
(166, 'ICU Management, Ethics and Law', 'The Critical care unit manager as an overall seer of the unit activities can employed one of the following as a principle of organizing the unit to achieve the organizational objectives.', '["Planning", "Directing", "Balance", "Motivation"]'::jsonb, 2, 'Balance is applied as an organising principle to keep unit activities effectively coordinated.', 'Ethics, Law & Management'),
(167, 'ICU Management, Ethics and Law', 'Which level of management is responsible for implementing programs that are intended to carry out the broader objectives of an organization set by executives?', '["chief financial managers", "middle managers", "first level managers", "supervisory managers"]'::jsonb, 1, 'Middle managers carry out programmes to achieve the broad objectives set by top executives.', 'Ethics, Law & Management'),
(168, 'ICU Management, Ethics and Law', 'Conflict arising from unclear or overlapping job expectations between two staff members is known as:', '["Distributive conflict", "Role conflict", "Intrapersonal conflict", "Intragroup conflict"]'::jsonb, 1, 'When it''s unclear who is responsible for what, that ambiguity itself becomes a source of conflict.', 'Ethics, Law & Management'),
(169, 'ICU Management, Ethics and Law', 'A hospital''s quality assurance team is performing a prospective audit. This audit would involve:', '["Reviewing and establishing new policies and procedures before they are implemented", "Reviewing the outcomes of a patient''s treatment after they leave the hospital", "Examining the care provided to a patient in real-time", "Analyzing a patient''s chart after a critical event has occurred"]'::jsonb, 0, 'A prospective audit looks at the future. It involves the evaluation of proposed policies, procedures, or care plans before they are put into practice to ensure they meet quality standards and are likely to lead to positive outcomes.', 'Ethics, Law & Management'),
(170, 'ICU Management, Ethics and Law', 'As an ICU manager you are aware that a formal document that most supervisors or managers keep for future reference is called', '["Incident reporting", "Report writing", "Incident writing", "Incident report"]'::jsonb, 3, 'A formal record kept by supervisors for future reference describing an event is an incident report.', 'Ethics, Law & Management'),
(171, 'ICU Management, Ethics and Law', 'The type of audit that involves reviewing a patient''s chart while they are still in the hospital is called a:', '["Outcome audit", "Prospective audit", "Retrospective audit", "Concurrent audit"]'::jsonb, 3, 'A concurrent audit occurs simultaneously with the patient''s care. This allows for real-time intervention and can help to prevent potential problems before they lead to poor patient outcomes.', 'Ethics, Law & Management'),
(172, 'ICU Management, Ethics and Law', 'The last function in the sequence, which culminates in the attainment of organization objectives, is:', '["coordinating", "controlling", "organizing", "planning"]'::jsonb, 1, 'Controlling is the final function in the cycle; it checks whether objectives have been achieved.', 'Ethics, Law & Management'),
(173, 'ICU Management, Ethics and Law', 'The Belmont Report''s 3 core ethical principles are:', '["Honesty, Accuracy, Transparency", "Consent, Privacy, Fairness", "Safety, Dignity, Respect", "Autonomy, Beneficence, Justice"]'::jsonb, 3, 'These three principles form the foundational framework most modern research ethics guidelines build upon.', 'Ethics, Law & Management'),
(174, 'ICU Management, Ethics and Law', 'Which management principle promotes employee participation in decision-making?', '["Discipline", "Centralization", "Unity of command", "Decentralization"]'::jsonb, 3, 'Decentralisation distributes decision-making authority, promoting employee participation.', 'Ethics, Law & Management'),
(175, 'ICU Management, Ethics and Law', 'Which document outlines the duties and responsibilities of a staff nurse?', '["Job description", "Nursing care plan", "Ward report", "Duty roster"]'::jsonb, 0, 'A job description formally outlines the duties, responsibilities, and expectations of a role.', 'Ethics, Law & Management'),
(176, 'ICU Management, Ethics and Law', 'Clinical audit in the ICU is an important part of:', '["Building maintenance", "Payroll management", "Clinical governance", "Hospital marketing"]'::jsonb, 2, 'Other parts include risk management, education, research and patient involvement.', 'Ethics, Law & Management'),
(177, 'ICU Management, Ethics and Law', 'Which handover practice is most likely to improve safety in ICU?', '["Skipping handover when the unit is busy", "A structured bedside handover with a checklist", "Handing over by text message only", "A quick corridor chat with no notes"]'::jsonb, 1, 'Bedside handover lets both nurses check the patient, lines, pumps and alarms.', 'Ethics, Law & Management'),
(178, 'ICU Management, Ethics and Law', 'A ''par level'' stock system in ICU ensures that:', '["Each nurse buys their own supplies", "Items are ordered only after they run out", "A minimum stock of each item is kept at all times", "Expired stock is used first"]'::jsonb, 2, 'It prevents shortages of emergency drugs and consumables.', 'Ethics, Law & Management'),
(179, 'ICU Management, Ethics and Law', 'Buying a new ventilator for the ICU falls under the:', '["Petty cash budget", "Operating budget", "Capital budget", "Personnel budget"]'::jsonb, 2, 'Operating budgets cover recurring costs such as consumables and utilities.', 'Ethics, Law & Management'),
(180, 'ICU Management, Ethics and Law', 'The ABCDEF bundle used in ICU is mainly aimed at:', '["Increasing the use of physical restraints", "Shortening the family visiting hours", "Reducing staff numbers on night shifts", "Reducing delirium, weakness and time on the ventilator"]'::jsonb, 3, 'A: assess pain; B: both SAT and SBT; C: choice of sedation; D: delirium; E: early mobility; F: family.', 'Ethics, Law & Management'),
(181, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Which contrast media type is preferred in high-risk patients such as those with renal failure, cardiac failure, or diabetes mellitus?', '["Non-ionic (Low Osmolar) contrast media", "Barium sulfate only", "Ionic (High Osmolar) contrast media", "No contrast is ever needed in high-risk patients"]'::jsonb, 0, 'Non-ionic/Low Osmolar Contrast Media (LOCM) cause fewer reactions and are preferred in high-risk groups including renal failure, cardiac failure, diabetes, sickle cell disease and the elderly.', 'Research & Nursing Process'),
(182, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A nurse assesses a client''s exercise habits, activities of daily living, and any factors that interfere with the client''s desired activity level (such as dyspnea or chest pain). This corresponds to which Gordon functional health pattern?', '["Activity-exercise pattern", "Self-perception-self-concept pattern", "Nutritional-metabolic pattern", "Sleep-rest pattern"]'::jsonb, 0, 'The activity-exercise pattern describes the client''s pattern of exercise, activity, leisure, and recreation, as well as factors like cardiovascular or respiratory symptoms that limit desired activity.', 'Research & Nursing Process'),
(183, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A researcher writes: ''What are the lived experiences of family members of patients admitted to the ICU?'' This is best classified as a', '["Null hypothesis", "Qualitative research question", "Statistical hypothesis requiring inferential testing", "Directional hypothesis"]'::jsonb, 1, 'This open-ended question exploring lived experience is characteristic of qualitative research questions rather than a hypothesis, which requires measurable variables and predicted relationships.', 'Research & Nursing Process'),
(184, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A researcher wants to explore in depth the coping strategies of five ICU nurses who have personally experienced a patient''s cardiac arrest during their shift, deliberately selecting nurses with this specific experience. This is an example of', '["Purposive sampling", "Simple random sampling", "Cluster sampling", "Systematic sampling"]'::jsonb, 0, 'Deliberately selecting participants because they possess a specific, relevant experience (surviving a patient cardiac arrest event) is characteristic of purposive sampling.', 'Research & Nursing Process'),
(185, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Per current evidence-based critical care nutrition guidance, gastric residual volume (GRV) monitoring should generally prompt the nurse to hold or reassess feeding when the volume exceeds approximately:', '["50 mL", "500 mL", "1500 mL", "GRV should never be checked regardless of volume"]'::jsonb, 1, 'Current guidance from major critical care nutrition societies suggests holding or reassessing feeds when GRV exceeds approximately 500 mL, since routinely stopping feeds at lower volumes has not been shown to reduce aspiration risk and can lead to unnecessary underfeeding.', 'Research & Nursing Process'),
(186, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Mr Zee says his heart pounds and he is short of breath on the stairs. The nurse then auscultates the heart and checks the pulse. The nurse is:', '["Collecting data", "Processing data into information", "Validating data", "Organising data"]'::jsonb, 2, 'Checking pulse and heart sounds to confirm a subjective complaint (palpitations, breathlessness) is validating data.', 'Research & Nursing Process'),
(187, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A nurse reviewing an electronic health record to identify a client''s past surgical history and allergies is using which source and method of data collection?', '["Secondary source, record review method", "Secondary source, physical examination method", "Primary source, observation method", "Primary source, interview method"]'::jsonb, 0, 'The health record is a secondary source, and reviewing it is the record review method of data collection.', 'Research & Nursing Process'),
(188, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A patient''s marital status (single, married, divorced, widowed) recorded in a research questionnaire is measured on which scale?', '["Ratio", "Ordinal", "Nominal", "Interval"]'::jsonb, 2, 'Marital status categories have no inherent numeric order, making this a nominal-level variable.', 'Research & Nursing Process'),
(189, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Which of the following data collection methods relies most heavily on the nurse''s use of the senses (sight, hearing, smell, touch) without direct questioning of the client?', '["Consultation with the physician", "Observation", "Chart review", "Interview"]'::jsonb, 1, 'Observation relies on the nurse''s senses to gather data about the client''s appearance, behavior, and environment without direct questioning.', 'Research & Nursing Process'),
(190, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', '______ describes the present state of affairs as it exists without having any control over variables.', '["Descriptive research", "Distinctive research", "Applied research", "Analytical research"]'::jsonb, 0, 'Descriptive research describes existing conditions without manipulating variables.', 'Research & Nursing Process'),
(191, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'The assessment approach in which the cardiovascular system is assessed before the genito-urinary system is the:', '["Systematic approach", "Cephalocaudal approach", "Body systems approach", "Approach by order of priority"]'::jsonb, 2, 'The body systems approach assesses one system at a time, e.g. cardiovascular before genito-urinary.', 'Research & Nursing Process'),
(192, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A literature review that is organized by grouping studies according to recurring topics or findings, rather than simply listing them chronologically, is following a', '["Random and unstructured approach", "Purely alphabetical listing with no analysis", "Approach that ignores all study findings", "Thematic organization approach"]'::jsonb, 3, 'Thematic organization groups related studies and findings around key concepts or themes, producing a more coherent and analytical review than a simple list.', 'Research & Nursing Process'),
(193, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Before a data collection tool (such as a questionnaire) is used in the main study, it should first undergo:', '["Immediate distribution to all participants without review", "Full statistical analysis of anticipated results", "Translation into as many languages as possible regardless of relevance", "Pilot testing to check its clarity, validity, and reliability"]'::jsonb, 3, 'Pilot testing on a small group prior to the main study helps identify problems with clarity, validity, and reliability of the instrument before full-scale use.', 'Research & Nursing Process'),
(194, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A survey of ICU nurses'' knowledge and attitudes toward pain assessment in non-verbal patients, without any intervention, best exemplifies a', '["Quasi-experimental research design with two groups", "True experimental research design", "Descriptive research design", "Case-control design"]'::jsonb, 2, 'This study simply describes existing knowledge and attitudes without manipulating any variable, which is the hallmark of a descriptive design.', 'Research & Nursing Process'),
(195, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A jejunal (post-pyloric) feeding tube is generally preferred over a gastric feeding tube in which situation?', '["A patient with gastroparesis or a high risk of aspiration", "A patient with a normal swallow evaluation", "A patient with normal gastric emptying and low aspiration risk", "A patient who will be extubated within 24 hours"]'::jsonb, 0, 'Post-pyloric (jejunal) feeding bypasses the stomach and is associated with a lower risk of reflux and aspiration, making it preferable in patients with delayed gastric emptying (gastroparesis) or a high aspiration risk.', 'Research & Nursing Process'),
(196, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Ionic (High Osmolar) contrast media, compared to non-ionic (Low Osmolar) contrast media, are associated with:', '["More side effects but lower cost", "No side effects at any dose", "Fewer side effects and higher cost", "Identical side-effect profile and cost"]'::jsonb, 0, 'Ionic/HOCM agents dissociate into ions, have high osmolality, and cause more reactions, but are cheaper than non-ionic/LOCM agents such as iohexol.', 'Research & Nursing Process'),
(197, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'ICU-acquired weakness is best reduced by:', '["Routine deep sedation for all patients", "Strict bed rest until ICU discharge", "Higher doses of steroids", "Early mobilisation and minimising sedation"]'::jsonb, 3, 'Physiotherapy can start safely even in ventilated patients.', 'Research & Nursing Process'),
(198, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'In an electronic health record, an audit trail is used to:', '["Record who accessed or changed each record and when", "Speed up the hospital computer system", "Print discharge summaries automatically", "Delete old patient files automatically"]'::jsonb, 0, 'It supports confidentiality and accountability.', 'Research & Nursing Process'),
(199, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A potassium result of 6.9 mmol/L comes back from a difficult blood draw in a patient with a normal ECG. The nurse should suspect:', '["A haemolysed sample; arrange a repeat sample", "Normal value for an ICU patient", "Definite hyperkalaemia; give insulin at once", "Laboratory error in sodium only"]'::jsonb, 0, 'Red cells release potassium when damaged. Still check the ECG and the clinical picture.', 'Research & Nursing Process'),
(200, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Procalcitonin is used in ICU mainly to help:', '["Guide when to stop antibiotics in bacterial infection", "Measure kidney function in AKI", "Monitor anticoagulation with heparin", "Diagnose an acute myocardial infarction"]'::jsonb, 0, 'Falling levels support stopping antibiotics earlier.', 'Research & Nursing Process');
insert into public.questions (id, topic, source, q, opts, ans_idx, exp, category, category_icon, is_active)
insert into public.exam_exams (title, instructions, starts_at, ends_at, duration_minutes, question_ids,
